def check(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def sha(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1 << 20), b""):
            digest.update(block)
    return digest.hexdigest()


def files(folder: Path) -> dict[str, str]:
    return {p.relative_to(folder).as_posix(): sha(p) for p in sorted(folder.rglob("*")) if p.is_file()}


def classpath_manifest(entries: list[Path]) -> list[dict[str, object]]:
    result = []
    for entry in entries:
        path = entry.resolve(strict=True)
        if path.is_dir():
            check(not any(p.is_symlink() for p in path.rglob("*")), "Frozen runtime contains a symlink")
            identities = files(path)
            digest = hashlib.sha256()
            for name in sorted(identities, key=Path):
                digest.update(name.encode() + b"\0")
                digest.update(bytes.fromhex(identities[name]))
            result.append({"path": str(path), "kind": "tree", "files": len(identities),
                           "sha256": digest.hexdigest()})
        else:
            check(path.is_file(), "Invalid frozen classpath entry")
            result.append({"path": str(path), "kind": "file", "sha256": sha(path)})
    return result


def write_json(path: Path, value: object) -> None:
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n")


def environment() -> dict[str, str]:
    env = os.environ.copy()
    env["JAVA_HOME"] = str(JAVA_HOME)
    env["PATH"] = str(JAVA_HOME / "bin") + os.pathsep + env.get("PATH", "")
    return env


def run(out: Path, label: str, command: list[object]) -> dict[str, object]:
    record = {
        "argv": [str(value) for value in command],
        "cwd": str(ROOT),
        "started": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "startedEpochNs": time.time_ns(),
    }
    write_json(out / (label + "-command.json"), record)
    print(label + " started " + str(record["started"]), flush=True)
    with (out / (label + ".log")).open("wb") as log:
        result = subprocess.run(record["argv"], cwd=ROOT, env=environment(), stdout=log, stderr=subprocess.STDOUT)
    record.update(exit_code=result.returncode, finished=datetime.datetime.now(datetime.timezone.utc).isoformat())
    write_json(out / (label + "-command.json"), record)
    print(label + " exited " + str(result.returncode), flush=True)
    return record


def copy_overlay(source: Path, destination: Path) -> None:
    for path in sorted(source.rglob("*")):
        if path.is_file():
            target = destination / path.relative_to(source)
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(path, target)


def copied_pom(out: Path, classes: Path, tests: Path) -> Path:
    namespace = "http://maven.apache.org/POM/4.0.0"
    ET.register_namespace("", namespace)
    tree = ET.parse(MODULE / "pom.xml")
    root = tree.getroot()

    def name(tag: str) -> str:
        return "{" + namespace + "}" + tag

    parent = root.find(name("parent"))
    relative = parent.find(name("relativePath"))
    if relative is None:
        relative = ET.SubElement(parent, name("relativePath"))
    relative.text = str(ROOT / "core/sail/pom.xml")
    build = root.find(name("build"))
    for tag, value in (
        ("directory", out / "target"),
        ("outputDirectory", classes),
        ("testOutputDirectory", tests),
        ("testSourceDirectory", HERE / "test-src"),
    ):
        item = build.find(name(tag))
        if item is None:
            item = ET.SubElement(build, name(tag))
        item.text = str(value)
    path = out / "pom.xml"
    tree.write(path, encoding="utf-8", xml_declaration=True)
    return path


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("stage", help="Fresh, simple validation directory name")
    parser.add_argument("--mode", required=True, choices=("red", "green"))
    parser.add_argument("--overlay", type=Path, help="Compiled accounting prefix; required only for green")
    parser.add_argument("--red-validation", type=Path, default=HERE / "validation/red-v1",
                        help="Accepted red-stage directory whose source/dependency identities green must preserve")
    parser.add_argument("--slot-granted", action="store_true")
    args = parser.parse_args()
    check(args.slot_granted, "Coordinator must grant the exclusive Java slot after the mandatory root build")
    check(re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]*", args.stage) is not None, "Invalid stage directory name")
    check((args.mode == "green") == (args.overlay is not None), "Only green takes a compiled accounting overlay")
    check(sha(TEST_SOURCE) == TEST_SOURCE_SHA, "Sealed contract assertions changed")
    if args.mode == "red":
        check(sha(STUB_SOURCE) == STUB_SOURCE_SHA, "Sealed red-only stub changed")
    red_directory = None
    if args.mode == "green":
        red_directory = args.red_validation.resolve(strict=True)
        red_receipt = json.loads((red_directory / "validation-receipt.json").read_text())
        check(red_receipt["mode"] == "red" and red_receipt["passedStage"]
              and red_receipt["testSourceSha256"] == TEST_SOURCE_SHA,
              "Green requires accepted red evidence for these exact contract assertions")
        check(sha(red_directory / TEST_SOURCE.name) == TEST_SOURCE_SHA, "Archived red contract source changed")
    check(sha(BASE_DESCRIPTOR) == BASE_DESCRIPTOR_SHA, "Prior publication runtime descriptor changed")
    source_cases = set(re.findall(r"@Test\s+void\s+(\w+)\(", TEST_SOURCE.read_text()))
    check(source_cases == EXPECTED_TESTS, "Contract selection differs from the declared fifteen cases")
    descriptor = json.loads(BASE_DESCRIPTOR.read_text())
    cp_file = Path(descriptor["classpathFile"])
    check(sha(cp_file) == descriptor["classpathFileSha256"], "Prior frozen classpath text changed")
    cp = cp_file.read_text().strip()
    entries = [Path(value) for value in cp.split(os.pathsep)]
    check(len(entries) == 129, "Unexpected prior publication classpath shape")
    manifest_file = Path(descriptor["classpathManifestFile"])
    check(sha(manifest_file) == descriptor["classpathManifestFileSha256"], "Prior frozen classpath manifest changed")
    manifest = classpath_manifest(entries)
    check(manifest == json.loads(manifest_file.read_text()), "Prior frozen runtime bytes changed")
    production_entry = entries[descriptor["productionEntryIndex"]]
    test_entry = entries[descriptor["productionEntryIndex"] - 1]
    check(test_entry.name == "000-test-classes", "Unexpected original test-class entry")

    out = HERE / "validation" / args.stage
    out.mkdir(parents=True, exist_ok=False)
    shutil.copyfile(Path(__file__), out / "runner-at-launch.py")
    shutil.copyfile(TEST_SOURCE, out / TEST_SOURCE.name)
    write_json(out / "base-classpath-manifest.json", manifest)
    before = files(MODULE / "src")
    write_json(out / "sources-before.json", before)
    classes, tests = out / "classes", out / "test-classes"
    shutil.copytree(production_entry, classes)
    shutil.copytree(test_entry, tests)
    copy_overlay(BASE / "classes", classes)
    if args.overlay is not None:
        overlay = args.overlay.resolve(strict=True)
        copy_overlay(overlay, classes)
        write_json(out / "overlay-class-files.json", files(overlay))
    sources = [TEST_SOURCE]
    if args.mode == "red":
        shutil.copyfile(STUB_SOURCE, out / STUB_SOURCE.name)
        sources.append(STUB_SOURCE)
    command = [JAVA_HOME / "bin/javac", "--release", "25", "-proc:none", "-implicit:none", "-sourcepath", "",
               "-cp", os.pathsep.join([str(classes), str(tests), cp]), "-d", tests, *sources]
    compiled = run(out, "compile-contract", command)
    if compiled["exit_code"]:
        print((out / "compile-contract.log").read_text(errors="replace"))
        raise SystemExit("Contract compilation failed; this is not red evidence")
    write_json(out / "production-class-files.json", files(classes))
    write_json(out / "test-class-files.json", files(tests))
    (out / "target/tmp/fork-1").mkdir(parents=True)
    pom = copied_pom(out, classes, tests)
    command = [MAVEN, "-o", "-Dmaven.repo.local=.m2_repo", "-Pquick", "-DskipTests=false", "-f", pom,
               "-Dtest=" + CLASS_NAME, "-DforkCount=1", "-Drdf4j.lmdb.test.maxHeap=4G",
               "-Drdf4j.lmdb.resultCoordinateTransport=dense", "-Dsurefire.runOrder=alphabetical", "surefire:test"]
    executed = run(out, "tests", command)
    reports = out / "surefire-reports"
    reports.mkdir()
    totals = dict(classes=0, tests=0, failures=0, errors=0, skipped=0)
    snippets, cases = [], []
    execution_classpath = None
    for path in sorted((out / "target/surefire-reports").glob("*")):
        if not path.is_file():
            continue
        check(path.stat().st_mtime_ns >= executed["startedEpochNs"], "Unexpected stale report: " + str(path))
        shutil.copyfile(path, reports / path.name)
        if path.name.startswith("TEST-") and path.suffix == ".xml":
            suite = ET.parse(path).getroot()
            properties = {p.attrib["name"]: p.attrib.get("value", "")
                          for p in suite.findall("./properties/property")}
            execution_classpath = properties.get("surefire.test.class.path")
            totals["classes"] += 1
            for key in ("tests", "failures", "errors", "skipped"):
                totals[key] += int(suite.attrib.get(key, 0))
            for case in suite.findall("testcase"):
                failure = case.find("failure")
                cases.append({"classname": case.attrib["classname"], "name": case.attrib["name"],
                              "failure": failure is not None, "error": case.find("error") is not None,
                              "skipped": case.find("skipped") is not None,
                              "failureMessage": None if failure is None else failure.attrib.get("message", "")})
        elif path.suffix == ".txt":
            snippets.extend(line for line in path.read_text(errors="replace").splitlines()
                            if line.startswith("Tests run:"))
    write_json(out / "results.json", totals)
    write_json(out / "test-cases.json", cases)
    check(execution_classpath is not None, "Surefire did not expose its actual test classpath")
    executed_entries = [Path(value) for value in execution_classpath.split(os.pathsep)]
    check([path.resolve() for path in executed_entries[:2]] == [tests.resolve(), classes.resolve()],
          "Surefire did not use the isolated test/production copies first")
    execution_manifest = classpath_manifest(executed_entries)
    write_json(out / "execution-classpath-manifest.json", execution_manifest)
